function sumar(datos) {
  let total = 0;
  for (let i = 0; i < datos.length; i = i + 1) {
    total = total + datos[i];
  }
  return total;
}

function contarHeladas(temperaturas) {
  let cantidad = 0;
  for (let i = 0; i < temperaturas.length; i = i + 1) {
    if (temperaturas[i] < 0) { cantidad = cantidad + 1; }
  }
  return cantidad;
}
